const $ = (s,root=document) => root.querySelector(s);
const calendar = $('#days');
const state = { selected:new Set(), page:0, theaters:[], data:null, filmImages:{}, filmSummaries:{}, design:new URLSearchParams(location.search).get('view')==='design' };
// Venues that are not scraped; excluded from the filter chips and the day columns.
function dayCount(){const v=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--days'),10);return v>0?v:5;}
let renderedDays=0;
const otherTheaters = new Set(['lincoln','moma','angelika','paris','momi','spectacle']);
const nyParts = (date=new Date()) => Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(x=>[x.type,x.value]));
const today = () => {const p=nyParts();return `${p.year}-${p.month}-${p.day}`;};
const addDays=(date,n)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const el=(tag,cls,content)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(content!==undefined)e.textContent=content;return e;};
const external=(url)=>{try{const u=new URL(url);return /^https?:$/.test(u.protocol)?u.href:null}catch{return null}};
function timeLabel(value){const [h,m]=value.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function buildFilters(){const nav=$('#filters');state.theaters.filter(v=>!otherTheaters.has(v.id)).forEach(v=>{const b=el('button','chip',v.name);b.type='button';b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{state.selected.has(v.id)?state.selected.delete(v.id):state.selected.add(v.id);b.setAttribute('aria-pressed',String(state.selected.has(v.id)));renderDays()});const address=()=>{$('#address').textContent=v.address;};b.addEventListener('pointerenter',address);b.addEventListener('focus',address);b.addEventListener('pointerleave',()=>{$('#address').textContent=''});b.addEventListener('blur',()=>{$('#address').textContent=''});nav.append(b)});}
function designData(){const films=[['Persona','Ingmar Bergman',1966,'35mm','14:00'],['The Conformist','Bernardo Bertolucci',1970,'','16:15'],['Possession','Andrzej Żuławski',1981,'35mm','19:00']];let screenings=[];for(let d=0;d<30;d++)state.theaters.forEach((v,i)=>{films.forEach((f,j)=>screenings.push({id:`demo-${d}-${i}-${j}`,title:f[0],director:f[1],year:f[2],format:f[3],date:addDays('2026-09-06',d),venue:v.id,showtimes:[f[4]],ticketUrl:v.sourceUrl,imageUrl:state.filmImages[f[0]],description:{Persona:'An actress and her nurse confront unstable identities and emotional power in Ingmar Bergman’s chamber drama.',"The Conformist":'A morally vacant functionary embraces fascism while confronting the life he abandoned in Bernardo Bertolucci’s political drama.',Possession:'A marriage’s collapse becomes a feverish nightmare of espionage, bodily horror, and divided identity in Cold War Berlin.'}[f[0]]}));if(i===1) films.slice(0,2).forEach((f,j)=>screenings.push({id:`extra-${d}-${j}`,title:f[0],director:f[1],year:f[2],format:f[3],date:addDays('2026-09-06',d),venue:v.id,showtimes:[f[4]],ticketUrl:v.sourceUrl,imageUrl:state.filmImages[f[0]],description:{Persona:'An actress and her nurse confront unstable identities and emotional power in Ingmar Bergman’s chamber drama.',"The Conformist":'A morally vacant functionary embraces fascism while confronting the life he abandoned in Bernardo Bertolucci’s political drama.',Possession:'A marriage’s collapse becomes a feverish nightmare of espionage, bodily horror, and divided identity in Cold War Berlin.'}[f[0]]}));});return {mode:'design',screenings,festivals:[{title:'NYFF64',venue:'FILM AT LINCOLN CENTER',dates:'SEP 25 – OCT 12',url:'https://www.filmlinc.org/nyff2026/'},{title:'CLAIRE DENIS: COMPLETE RETROSPECTIVE',venue:'BAM',dates:'OCT 3 – OCT 18',url:'https://www.bam.org/film'},{title:'JAPANESE HORROR 1980–2005',venue:'METROGRAPH',dates:'SEP 12 – SEP 27',url:'https://metrograph.com/series/'}]};}
function renderDays(){hideFilmPreview();calendar.replaceChildren();const base=state.design?'2026-09-06':today();const now=nyParts();const minute=`${now.hour}:${now.minute}`;const included=state.theaters.filter(v=>!otherTheaters.has(v.id)&&(!state.selected.size||state.selected.has(v.id)));const span=dayCount();renderedDays=span;for(let i=0;i<span;i++){const offset=state.page*span+i;const date=addDays(base,offset);const d=new Date(date+'T12:00:00Z');const column=el('section','day');const heading=el('h2','date');const weekday=new Intl.DateTimeFormat('en-US',{weekday:'long',timeZone:'UTC'}).format(d);heading.append(el('span','',`${offset===0?'Today, ':offset===1?'Tomorrow, ':''}${weekday}`),document.createElement('br'),document.createTextNode(new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}).format(d)));column.append(heading);const list=el('div','list');list.tabIndex=0;list.setAttribute('aria-label',`${weekday} screenings`);let hasListings=false;const rendered=new Set();included.forEach(v=>{const entries=state.data.screenings.filter(f=>f.date===date&&f.venue===v.id);if(!entries.length)return;hasListings=true;rendered.add(v.id);const group=el('section','venue');const venueHeading=el('h3','',v.name);const status=state.data.venues?.[v.id];if(status?.status==='stale')venueHeading.title='Showing the last successful update; check the theater for changes.';group.append(venueHeading);entries.forEach(f=>{const url=external(f.ticketUrl);const a=el(url?'a':'div','screening');if(url){a.href=url;a.target='_blank';a.rel='noopener noreferrer';}a.dataset.id=f.id||`${v.id}-${date}-${f.title}`;const times=el('span','times');f.showtimes.forEach((t,j)=>{if(j)times.append(document.createTextNode(', '));times.append(el('span',`showtime ${!state.design&&date===base&&t<minute?'elapsed':''}`,timeLabel(t)))});a.append(times,el('span','title',f.title+(f.format&&f.format.toLowerCase()!=='dcp'?`, ${f.format}`:'')));const credits=[f.director,f.year].filter(Boolean).join(', ');if(credits)a.append(el('span','credits',credits));bindFilmPreview(a,f);group.append(a)});list.append(group)});
if(!hasListings){const missing=included.some(v=>['unavailable','stale','partial'].includes(state.data.venues?.[v.id]?.status));const empty=el('p','empty',missing?'Complete listings are unavailable for this date.':'No published screenings for this date.');list.append(empty);included.forEach(v=>{const p=el('p','empty');const link=el('a','',`Check ${v.name}`);link.href=v.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';p.append(link);list.append(p)});}if(hasListings&&!state.design){for(const v of included){if(rendered.has(v.id))continue;const status=state.data.venues?.[v.id];if(!status||status.status==='ok')continue;const note=el('section','venue coverage-note');note.append(el('h3','',v.name));const message=status.status==='partial'?'Special events only.':status.status==='stale'?'Last available listings shown.':'Listings unavailable.';const p=el('p','empty',message);const link=el('a','', 'Check the full program ↗');link.href=v.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';p.append(el('br'),link);note.append(p);list.append(note)}}list.addEventListener('scroll',()=>list.classList.toggle('scrolled',list.scrollTop>4),{passive:true});column.append(list);calendar.append(column);if(state.design&&i===0&&!state.selected.size&&!state.page)requestAnimationFrame(()=>{list.scrollTop=49})}calendar.scrollLeft=0;$('#previous').disabled=state.page===0;$('#next').setAttribute('aria-label',`Next ${span} days`);$('#previous').setAttribute('aria-label',`Previous ${span} days`);}
function renderFestivals(){const root=$('#festivals');root.replaceChildren();for(const f of state.data.festivals||[]){if(state.selected.size&&f.venueId&&!state.selected.has(f.venueId))continue;const item=el('div','festival');item.append(el('span','flower','✿'));const copy=el('p');const link=el('a','',f.title);link.href=external(f.url)||'#';link.target='_blank';link.rel='noopener noreferrer';copy.append(link,el('br'),document.createTextNode(f.venue),el('br'),document.createTextNode(f.dates));item.append(copy);root.append(item)}if(!root.children.length)root.append(el('p','empty','New programming as announced.'));}
$('#next').addEventListener('click',()=>{state.page++;renderDays()});$('#previous').addEventListener('click',()=>{state.page=Math.max(0,state.page-1);renderDays()});
async function start(){try{const venueResponse=await fetch('data/theaters.json');if(!venueResponse.ok)throw new Error('venues');state.theaters=await venueResponse.json();try{const images=await fetch('data/film-images.json');if(images.ok)state.filmImages=(await images.json()).demo||{};}catch{}const summaries=await fetch('data/film-summaries.json');if(summaries.ok)state.filmSummaries=await summaries.json();if(state.design){state.data=designData();$('#updated').textContent='Design preview · sample listings';}else{const r=await fetch('data/screenings.json',{cache:'no-cache'});if(!r.ok)throw new Error('listings');state.data=await r.json();const gaps=Object.entries(state.data.venues||{}).filter(([,s])=>s.status!=='ok');$('#updated').title=gaps.length?`${gaps.length} venues have partial or unavailable listings. See each theater’s calendar for the full program.`:'';if(state.data.updatedAt){const t=nyParts(new Date(state.data.updatedAt));const hour=Number(t.hour);$('#updated').textContent=`Last updated ${t.month}/${t.day}/${t.year.slice(-2)} ${hour%12||12}:${t.minute}${hour>=12?'PM':'AM'}`;}else $('#updated').textContent='Listings awaiting first update';}buildFilters();renderDays();renderFestivals();}catch(error){$('#updated').textContent='Listings temporarily unavailable';calendar.replaceChildren(el('p','error','The calendar could not be loaded. Please refresh to try again.'));}}
start();

let lastDay=today();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!state.design&&state.data&&today()!==lastDay){lastDay=today();state.page=0;renderDays()}});
window.addEventListener('resize',()=>{if(state.data&&dayCount()!==renderedDays)renderDays();});
